/* Klachtenanalyse – vertaling van de (i)-uitleg en "? Uitleg data" (FR, EN, DE, ES, IT).
 * De Nederlandse tekst staat in info.js. Ontbreekt een veld hier, dan toont de tool het Nederlands.
 */
'use strict';

const C = (x) => '<code>' + x + '</code>';
const S = C(SRC);

const INFO_TR = {
  /* ═══════════════════════════ FRANÇAIS ═══════════════════════════ */
  fr: {
    filters: { t: 'Filtres', wat: "Tous les filtres se combinent (ET) : une plainte doit satisfaire chaque filtre rempli. Au sein d'un même filtre à choix multiples, un seul choix suffit (OU). Les nombres dans les listes portent sur toutes les plaintes chargées, pas seulement sur la sélection actuelle.", bron: ['Une ligne par plainte dans ' + S + ' (module de plaintes de WinPro, sur l’AS400).', 'Seules les plaintes à partir du 1/1/2020 sont chargées (' + C('KDATJJ &gt;= 2020') + ').'] },
    periode: { t: 'Période (date de la plainte)', wat: 'Affiche les plaintes dont la date de création se situe entre les deux dates (bornes incluses). Les raccourcis comptent à rebours à partir de la plainte la plus récente.', bron: [C('KDATE') + ' dans ' + S + ' : « date d’enregistrement », le jour de création de la plainte (format AAAAMMJJ).'], let: 'Il s’agit de la date de la plainte, pas de la livraison ou de la production du produit.' },
    pg: { t: 'Groupe de produits', wat: 'Le groupe de produits indiqué sur la plainte, p. ex. SO!, Tentes solaires, Screens, Volets, Fenêtres PVC. Les boutons Winsol, WinVista et WinBalu en bas de la liste cochent en un clic un ensemble fixe de groupes de produits.', bron: ['Code : ' + C('KPROD') + ' dans ' + S + ' (p. ex. 4S, 4A, 2A).', 'Description : ' + C('WINSOLPRO.PFPRODGRO') + ' (' + C('KO_PG') + ' → ' + C('OMS_PGN') + ').'], let: 'Sur l’AS400, « | » remplace le « ! » de la marque ; l’outil affiche SO! et Z!P. Les noms des groupes de produits proviennent de l’AS400 et restent en néerlandais.' },
    prod: { t: 'Produit', wat: 'Le produit (article) concerné par la plainte, p. ex. SO!Classic, Squaro, Solarfix.', bron: ['Code : ' + C('KARTNR') + ' dans ' + S + ' (numéro d’article, 3 chiffres).', 'Nom : ' + C('OARTLIB.PFPROD') + ' (' + C('PROD') + ' → ' + C('PRODBN') + ', dénomination néerlandaise).'], let: 'Les plaintes via le webshop ou sur des pièces détachées portent souvent sur un produit générique comme « WEBSHOP ARTIKEL HELIOS ». Le produit réel est alors inconnu ; utilisez TREE ou la description.' },
    tree: { t: 'TREE (défaut)', wat: 'L’arbre de choix rempli dans WinPro (onglet « Tree » de la plainte) : produit › type de problème › composant › détail, p. ex. SO! › WERKING › SENSOREN › Sensor defect › Temperatuursensor. Si vous choisissez un niveau supérieur, toutes les branches sous-jacentes sont incluses.', bron: [C('OORDLIB.PFKLACHTT') + ' : ' + C('TVOLGN') + ' (numéro de plainte), ' + C('TTREEID') + ' (id de la branche), ' + C('TTREEOM') + ' (chemin complet en texte).', 'Cette table est copiée chaque nuit de WinPro vers l’AS400.'], let: 'Une plainte peut avoir plusieurs chemins TREE et compte alors dans chaque chemin. TREE n’est vraiment utilisé que depuis 2024 (env. 35–40 % des plaintes). Les niveaux 1 à 3 sont fiables ; la suite est affichée comme un seul texte de détail. Les textes TREE restent en néerlandais.' },
    ntr: { t: 'Code NTR', wat: 'La catégorie NTR sous laquelle la plainte a été comptabilisée : la cause ou le responsable, p. ex. 13 Garantie, 8 Production, 7 Divers région, 9 Inscripteur, 12 Expédition.', bron: [C('KNNTR') + ' dans ' + S + ' : le code NTR confirmé.', 'S’il n’y a pas encore de code confirmé, l’outil utilise ' + C('KNTR') + ' (code NTR présumé). Le détail de la plainte indique alors « (présumé) ».', 'Description : ' + C('OORDLIB.PFKLACHTN') + ' (' + C('NNTR') + ' → ' + C('NOMSC') + ').'], let: '« NTR manquant » = ni code confirmé ni code présumé. Règle de base du QC : les plaintes sans code NTR ne sont pas comptées dans les analyses (à exclure via ce filtre).' },
    fout: { t: 'Code d’erreur', wat: 'Subdivision plus fine du code NTR, p. ex. 1302 Garantie Winsol, 1301 Garantie fournisseur. Les premiers chiffres renvoient au code NTR.', bron: [C('KNFOUT') + ' dans ' + S + ' (confirmé), sinon ' + C('KFOUT') + ' (présumé).', 'Description : ' + C('OORDLIB.PFKLACHTFO') + ' et ' + C('OORDLIB.PFKLACHTF2') + ' (' + C('UFOUT') + ' → ' + C('UOMSC') + ').'], let: 'Si un code apparaît comme « Fout 904 » sans nom, il ne figure dans aucune des deux tables de description.' },
    klant: { t: 'Client', wat: 'Le client au nom duquel la plainte est enregistrée (revendeur, menuisier, particulier…). Recherche possible par nom ou numéro.', bron: [C('KFIRMA') + ' + ' + C('KKLNR') + ' dans ' + S + '.', 'Nom et pays dans le fichier clients de la société : W = ' + C('WVDJ.PFKLAN') + ' (Winsol), B = ' + C('BADJ.PFKLAN') + ' (Winbalu), H = ' + C('HEDJ.PFKLAN') + ' (Helios) ; champs ' + C('KNAAM1') + ', ' + C('KNAT') + '.'], let: 'Un numéro de client n’est unique qu’avec la société. Presque toutes les plaintes sont sur la société W, y compris celles sur des produits Helios.' },
    status: { t: 'Statut', wat: 'La phase actuelle de la plainte, p. ex. en traitement, matériel prêt au magasin, au service de pose, clôturée.', bron: ['Code : ' + C('KFASE') + ' dans ' + S + '.', 'Description : ' + C('OORDLIB.PFKLACHTFA') + ' (' + C('OFASE') + ' → ' + C('OFASEOM') + ').'], let: 'C’est le statut d’aujourd’hui (au dernier rafraîchissement), pas le statut à la date de la plainte. Les noms de statut restent en néerlandais.' },
    vert: { t: 'Représentant', wat: 'Le représentant lié à la plainte. Un commercial ne voit que ses propres plaintes, un directeur celles des commerciaux de sa région.', bron: ['Numéro : ' + C('KVTNR') + ' dans ' + S + '.', 'Nom : ' + C('ODIVERS.PFVERT') + ' (' + C('VERTNR') + ' → ' + C('VNAAM') + ').'] },
    regio: { t: 'Région', wat: 'La région de vente de la plainte.', bron: ['Numéro : ' + C('KREGIO') + ' dans ' + S + '.', 'Nom : ' + C('ODIVERS.PFREGIO') + ' (' + C('REGIO') + ' → ' + C('REGPNN') + ').'], let: 'Certains numéros de région n’ont pas de nom dans la table ; seul le numéro est affiché.' },
    open: { t: 'Ouverte / clôturée', wat: 'Une plainte est <b>clôturée</b> si son statut est l’un de ceux-ci : A Plainte clôturée, W Plainte refusée, I Plainte pour info, O Plainte pour info (clôturée), Y Intervention refusée. Tous les autres statuts comptent comme <b>ouverts</b>.', bron: ['Déduit de ' + C('KFASE') + ' dans ' + S + '.'], let: 'Cette règle est fixée dans l’outil (pas dans l’AS400). « Plainte refusée par l’usine » (R) compte comme ouverte, comme dans le reporting du Controlling.' },
    terinfo: { t: 'Plaintes « pour info »', wat: 'Les plaintes avec le statut I (Plainte pour info) ou O (Plainte pour info, clôturée) sont des signalements sans réel traitement. Par défaut, elles ne sont pas comptées, comme dans le reporting du Controlling.', bron: ['Déduit de ' + C('KFASE') + ' dans ' + S + '.'] },
    actie: { t: 'Action à effectuer', wat: 'Le choix « Action à effectuer ? » de la plainte dans WinPro : ce qu’il faut faire pour résoudre la plainte. Une plainte avec l’action <b>Intervention</b> compte comme intervention : quelqu’un se rend sur place pour réparer. <b>Poser</b> se fait aussi sur place, mais pour poser du nouveau matériel.', bron: [C('KLEVPL') + ' dans ' + S + ' : 1 Livrer, 2 Poser, 3 Enlever, 4 Intervention, 5 Pour info, 0 non rempli.'], let: 'Le (I) à côté du numéro de plainte dans WinPro (champ ' + C('IINTVEN') + ', 1 = interne, I = via Extranet) signifie « intervention demandée » et figure comme info supplémentaire dans le détail. Pour les chiffres, c’est l’action qui compte.' },
    vervolg: { t: 'Suivi', wat: 'Un <b>dossier</b> est un seul problème. Une <b>plainte de suivi</b> est une nouvelle plainte sur le même problème, dans l’année qui suit la précédente : le problème n’a donc pas été résolu en une fois. C’est le cas si la plainte (1) est sur la commande de réparation (commande NTR) d’une plainte précédente, ou (2) est sur la même commande avec le même TREE (niveau 3). Une <b>autre plainte sur la même commande</b> est un nouveau problème sur une commande qui avait déjà une plainte : un dossier distinct.', bron: ['Commande de la plainte : ' + C('KORNR') + ' ; commande de réparation : ' + C('KNORDER') + ' ; ordre : ' + C('KDATE') + ', dans ' + S + '.', 'Sujet : TREE niveau 3 de ' + C('OORDLIB.PFKLACHTT') + '.'], let: 'Sans TREE, le sujet est inconnu ; une telle plainte sur la même commande compte prudemment comme « autre plainte ». Les numéros courts (1, 12, 43…) sont des numéros de région, pas des commandes. Le suivi est calculé sur toutes les plaintes, aussi hors des filtres actuels.' },
    kDos: { t: 'Dossiers', wat: 'Le nombre de dossiers distincts (problèmes uniques) auxquels appartiennent les plaintes de la sélection. Voir l’explication du filtre « Suivi ».', bron: ['Calculé dans l’outil à partir de ' + C('KORNR') + ', ' + C('KNORDER') + ' et ' + C('KDATE') + '.'] },
    kAnder: { t: 'Autre plainte sur la même commande', wat: 'Plaintes de la sélection sur une commande qui avait déjà une plainte antérieure, mais sur un autre problème (ou inconnu). Ce ne sont pas des plaintes de suivi ; elles forment leur propre dossier.', bron: ['Calculé dans l’outil ; voir le filtre « Suivi ».'] },
    kInterv: { t: 'Avec intervention', wat: 'Le nombre de plaintes de la sélection avec l’action « Intervention », et leur part dans toutes les plaintes de la sélection.', bron: [C('KLEVPL') + ' = 4 dans ' + S + '.'] },
    kVervolg: { t: 'Plaintes de suivi', wat: 'Le nombre de plaintes de la sélection qui sont le suivi d’une plainte antérieure du même dossier (dans l’année), et leur part.', bron: ['Calculé dans l’outil ; voir le filtre « Suivi ».'], let: 'Des plaintes récentes peuvent encore recevoir un suivi ; la part des derniers mois augmente donc encore.' },
    zoek: { t: 'Recherche', wat: 'Recherche le texte saisi (sans tenir compte des majuscules, aussi au milieu d’un mot) dans le texte libre de la plainte.', bron: [C('KOPM') + ' (description) et ' + C('KOPL') + ' (solution attendue) dans ' + S + '.', 'Cause, mesure corrective et action corrective de ' + C('OORDLIB.PFKLACHTBH') + ' (' + C('BOORZA') + ', ' + C('BCORRI') + ', ' + C('BCORRE') + ').'], let: 'Les plaintes sont saisies en néerlandais, français, allemand ou anglais : cherchez aussi le terme néerlandais (p. ex. « motor » à côté de « moteur »).' },
    kTotal: { t: 'Plaintes', wat: 'Le nombre de plaintes qui satisfont tous les filtres. Chaque plainte compte une fois, même si elle a plusieurs chemins TREE.', bron: ['Nombre de numéros de plainte uniques ' + C('KVOLGN') + ' dans ' + S + '.'] },
    kOpen: { t: 'Ouvertes', wat: 'Le nombre de plaintes de la sélection avec un statut ouvert (voir « Ouverte / clôturée »).', bron: ['Déduit de ' + C('KFASE') + ' dans ' + S + '.'] },
    kCost: { t: 'Coût NTR (matériel + pose)', wat: 'La somme des coûts comptabilisés sur les plaintes : le montant matériel plus le montant de pose, en euros.', bron: [C('KNBDRB') + ' (« montant erreur », matériel) + ' + C('KNWPL') + ' (« montant de pose ») dans ' + S + '.', 'Ce sont les montants de la comptabilisation NTR confirmée (également par comptabilisation dans ' + C('OORDLIB.PFKLACHTNT') + ').'], let: 'Les montants sont hors TVA. Les montants supérieurs à 100 000 € ou négatifs ne sont pas comptés : ce sont des erreurs de saisie (p. ex. un numéro de commande tapé dans le champ du montant).' },
    kLead: { t: 'Délai moyen de clôture', wat: 'Pour les plaintes clôturées de la sélection : le nombre moyen de jours calendrier entre la création et la clôture. Les plaintes ouvertes ne sont pas comptées.', bron: [C('KDATA') + ' (« 6. plainte clôturée ») − ' + C('KDATE') + ' (date d’enregistrement), dans ' + S + '.'], let: 'Quelques plaintes avec un très long délai peuvent fortement influencer la moyenne.' },
    kTree: { t: 'Avec TREE rempli', wat: 'La part des plaintes de la sélection qui ont au moins un chemin TREE.', bron: ['Plaintes avec au moins une ligne dans ' + C('OORDLIB.PFKLACHTT') + '.'], let: 'Plus ce pourcentage est bas, moins les graphiques et listes TREE sont représentatifs.' },
    evolutie: { t: 'Évolution', wat: 'Le nombre de plaintes (ou le coût NTR) par mois, trimestre ou année, selon la date de la plainte. Tous les filtres sont appliqués.', bron: ['Période : ' + C('KDATE') + ' dans ' + S + '.', 'Coût NTR : voir les chiffres clés.'], let: 'La dernière période n’est généralement pas encore complète et est donc plus basse.' },
    mode: { t: 'Graphique : ligne du temps ou années cumulées', wat: '<b>Ligne du temps</b> : la période choisie de gauche à droite, avec le nombre (ou le coût) par mois, trimestre ou année.<br><b>Intervention &amp; suivi</b> : par période, la part des plaintes avec intervention et la part des plaintes de suivi.<br><b>Années cumulées</b> : une ligne par année, de janvier à décembre, chaque semaine (ou mois) s’ajoutant à la précédente. On voit d’un coup d’œil si une année progresse plus vite ou plus lentement que les précédentes.', bron: ['Date de la plainte : ' + C('KDATE') + ' dans ' + S + '.'], let: 'En « Années cumulées », le filtre de période est ignoré (les autres filtres s’appliquent). L’année en cours s’arrête à la dernière plainte. Les semaines comptent à partir du 1er janvier (jours 1–7 = semaine 1) ; ce ne sont pas des semaines ISO. Les cases sous le graphique choisissent les années affichées ; votre choix est mémorisé dans ce navigateur.' },
    target: { t: 'Objectif année en cours', wat: 'Trace une ligne d’objectif en pointillés pour l’année en cours : la courbe cumulée de l’an dernier, réduite du pourcentage choisi. Si les plaintes de cette année restent sous cette ligne, vous êtes dans les clous.', bron: ['Calculé à partir de la ligne de l’an dernier dans la même sélection.'] },
    split: { t: 'Ventiler par', wat: 'Affiche une ligne par valeur au lieu d’un total. Les 7 plus grandes valeurs ont leur propre ligne, le reste est regroupé dans « Autres ».', bron: ['Les mêmes champs que les filtres du même nom.'], let: 'Pour TREE, les plaintes sans TREE ne comptent pas, et une plainte avec plusieurs chemins compte dans chaque chemin.' },
    top: { t: 'Où se situent les plaintes ?', wat: 'Les branches TREE, produits, codes NTR et clients les plus fréquents dans la sélection. Le pourcentage est la part du total des plaintes de la sélection. Cliquez sur une barre pour filtrer.', bron: ['TREE : ' + C('OORDLIB.PFKLACHTT') + '. Produits, codes NTR et clients : voir les filtres.'], let: 'Pour TREE, une plainte peut apparaître dans plusieurs branches ; les pourcentages peuvent dépasser 100 % au total.' },
    lijst: { t: 'Plaintes', wat: 'Les plaintes de la sélection, les plus récentes d’abord. Cliquez sur un titre de colonne pour trier, et sur une plainte pour tous les détails. « Exporter vers Excel » donne toute la sélection (pas seulement la page affichée).', bron: ['Détail de ' + S + ' : commande (' + C('KORNR') + '), commande NTR (' + C('KNORDER') + '), traité par (' + C('KBEHA') + '), dates par phase : en traitement (' + C('KDATB') + '), en magasin (' + C('KDATM') + '), au service de pose (' + C('KDATD') + '), résolue pour le client (' + C('KDATK') + '), clôturée (' + C('KDATA') + ').', 'Cause et mesures : ' + C('OORDLIB.PFKLACHTBH') + '.', '« Ouvrir dans WinPro » ouvre la plainte dans WinPro (uniquement sur le réseau Winsol).'] },
  },

  /* ═══════════════════════════ ENGLISH ═══════════════════════════ */
  en: {
    filters: { t: 'Filters', wat: 'All filters combine (AND): a complaint must meet every filter that is set. Within one multi-choice filter, one of the choices is enough (OR). The numbers in the lists count all loaded complaints, not just the current selection.', bron: ['One row per complaint in ' + S + ' (the WinPro complaints module, on the AS400).', 'Only complaints from 1/1/2020 are loaded (' + C('KDATJJ &gt;= 2020') + ').'] },
    periode: { t: 'Period (complaint date)', wat: 'Shows complaints whose creation date lies between the two dates (inclusive). The shortcuts count back from the most recent complaint in the data.', bron: [C('KDATE') + ' in ' + S + ': “date logged”, the day the complaint was created (format YYYYMMDD).'], let: 'This is the date of the complaint, not of delivery or production of the product.' },
    pg: { t: 'Product group', wat: 'The product group entered on the complaint, e.g. SO!, Awnings, Screens, Roller shutters, PVC windows. The Winsol, WinVista and WinBalu buttons at the bottom of the list tick a fixed set of product groups in one click.', bron: ['Code: ' + C('KPROD') + ' in ' + S + ' (e.g. 4S, 4A, 2A).', 'Description: ' + C('WINSOLPRO.PFPRODGRO') + ' (' + C('KO_PG') + ' → ' + C('OMS_PGN') + ').'], let: 'On the AS400, “|” stands where the brand writes “!”; the tool shows SO! and Z!P. Product group names come from the AS400 and stay in Dutch.' },
    prod: { t: 'Product', wat: 'The product (article) the complaint is about, e.g. SO!Classic, Squaro, Solarfix.', bron: ['Code: ' + C('KARTNR') + ' in ' + S + ' (article number, 3 digits).', 'Name: ' + C('OARTLIB.PFPROD') + ' (' + C('PROD') + ' → ' + C('PRODBN') + ', Dutch name).'], let: 'Complaints via the webshop or on spare parts are often on a collective product such as “WEBSHOP ARTIKEL HELIOS”. The actual product is then unknown; use TREE or the description.' },
    tree: { t: 'TREE (defect)', wat: 'The choice tree filled in in WinPro (the complaint’s “Tree” tab): product › type of problem › component › detail, e.g. SO! › WERKING › SENSOREN › Sensor defect › Temperatuursensor. Choosing a higher level includes all branches below it.', bron: [C('OORDLIB.PFKLACHTT') + ': ' + C('TVOLGN') + ' (complaint number), ' + C('TTREEID') + ' (branch id), ' + C('TTREEOM') + ' (full path as text).', 'This table is copied from WinPro to the AS400 every night.'], let: 'A complaint can have several TREE paths and then counts in each path. TREE has only really been used since 2024 (approx. 35–40% of complaints). Levels 1 to 3 are reliable; anything beyond is shown as one detail text. TREE texts stay in Dutch.' },
    ntr: { t: 'NTR code', wat: 'The NTR category the complaint was booked under: the cause or party responsible, e.g. 13 Warranty, 8 Production, 7 Regional miscellaneous, 9 Order entry, 12 Shipping.', bron: [C('KNNTR') + ' in ' + S + ': the confirmed NTR code.', 'If there is no confirmed code yet, the tool uses ' + C('KNTR') + ' (presumed NTR code). The complaint detail then says “(presumed)”.', 'Description: ' + C('OORDLIB.PFKLACHTN') + ' (' + C('NNTR') + ' → ' + C('NOMSC') + ').'], let: '“NTR missing” = neither a confirmed nor a presumed code. QC base rule: complaints without an NTR code are not counted in analyses (exclude them with this filter).' },
    fout: { t: 'Error code', wat: 'Finer breakdown within the NTR code, e.g. 1302 Warranty Winsol, 1301 Warranty supplier. The first digits refer to the NTR code.', bron: [C('KNFOUT') + ' in ' + S + ' (confirmed), otherwise ' + C('KFOUT') + ' (presumed).', 'Description: ' + C('OORDLIB.PFKLACHTFO') + ' and ' + C('OORDLIB.PFKLACHTF2') + ' (' + C('UFOUT') + ' → ' + C('UOMSC') + ').'], let: 'If a code shows as “Fout 904” without a name, it is in neither description table.' },
    klant: { t: 'Customer', wat: 'The customer in whose name the complaint is registered (dealer, joiner, private customer…). Search by name or number.', bron: [C('KFIRMA') + ' + ' + C('KKLNR') + ' in ' + S + '.', 'Name and country from that company’s customer file: W = ' + C('WVDJ.PFKLAN') + ' (Winsol), B = ' + C('BADJ.PFKLAN') + ' (Winbalu), H = ' + C('HEDJ.PFKLAN') + ' (Helios); fields ' + C('KNAAM1') + ', ' + C('KNAT') + '.'], let: 'A customer number is only unique together with the company. Nearly all complaints are on company W, including those on Helios products.' },
    status: { t: 'Status', wat: 'The phase the complaint is in now, e.g. in progress, material ready in warehouse, at installation service, closed.', bron: ['Code: ' + C('KFASE') + ' in ' + S + '.', 'Description: ' + C('OORDLIB.PFKLACHTFA') + ' (' + C('OFASE') + ' → ' + C('OFASEOM') + ').'], let: 'This is today’s status (at the last refresh), not the status on the complaint date. Status names stay in Dutch.' },
    vert: { t: 'Sales representative', wat: 'The sales representative linked to the complaint. A sales user only sees their own complaints, a director those of the sales reps in their region.', bron: ['Number: ' + C('KVTNR') + ' in ' + S + '.', 'Name: ' + C('ODIVERS.PFVERT') + ' (' + C('VERTNR') + ' → ' + C('VNAAM') + ').'] },
    regio: { t: 'Region', wat: 'The sales region of the complaint.', bron: ['Number: ' + C('KREGIO') + ' in ' + S + '.', 'Name: ' + C('ODIVERS.PFREGIO') + ' (' + C('REGIO') + ' → ' + C('REGPNN') + ').'], let: 'Some region numbers have no name in the lookup table; only the number is shown.' },
    open: { t: 'Open / closed', wat: 'A complaint counts as <b>closed</b> if its status is one of these: A Complaint closed, W Complaint rejected, I Complaint for info, O Complaint for info (closed), Y Intervention rejected. All other statuses count as <b>open</b>.', bron: ['Derived from ' + C('KFASE') + ' in ' + S + '.'], let: 'This rule is set in the tool itself (not in the AS400). “Complaint rejected by factory” (R) counts as open, as in Controlling’s reporting.' },
    terinfo: { t: '“For info” complaints', wat: 'Complaints with status I (Complaint for info) or O (Complaint for info, closed) are notifications without real complaint handling. By default they are not counted, as in Controlling’s complaints reporting.', bron: ['Derived from ' + C('KFASE') + ' in ' + S + '.'] },
    actie: { t: 'Action to be taken', wat: 'The “Action to be taken?” choice on the complaint in WinPro: what needs to be done to solve it. A complaint with action <b>Intervention</b> counts as an intervention: someone goes on site to repair. <b>Install</b> is also on site, but to install new material.', bron: [C('KLEVPL') + ' in ' + S + ': 1 Deliver, 2 Install, 3 Collect, 4 Intervention, 5 For info, 0 not filled in.'], let: 'The (I) next to the complaint number in WinPro (field ' + C('IINTVEN') + ', 1 = internal, I = via Extranet) means “intervention requested” and is shown as extra info in the complaint detail. The figures use the action, because it says what actually happens.' },
    vervolg: { t: 'Follow-up', wat: 'A <b>case</b> is one problem. A <b>follow-up complaint</b> is a next complaint about the same problem within 1 year of the previous one: the problem was not solved in one go. That is the case when the complaint (1) is on the repair order (NTR order) of an earlier complaint, or (2) is on the same order and has the same TREE (level 3). An <b>other complaint on the same order</b> is a new problem on an order that already had a complaint (different or unknown subject): a case of its own.', bron: ['Order of the complaint: ' + C('KORNR') + '; repair order: ' + C('KNORDER') + '; sequence: ' + C('KDATE') + ', in ' + S + '.', 'Subject: TREE level 3 from ' + C('OORDLIB.PFKLACHTT') + '.'], let: 'Without TREE the subject is unknown; such a complaint on the same order cautiously counts as “other complaint”, not as follow-up. Short order numbers (1, 12, 43…) are region numbers and do not count as orders. Follow-ups are calculated over all complaints, also those outside the current filters.' },
    kDos: { t: 'Cases', wat: 'The number of distinct cases (unique problems) the complaints in the selection belong to. See the explanation of the “Follow-up” filter.', bron: ['Calculated in the tool from ' + C('KORNR') + ', ' + C('KNORDER') + ' and ' + C('KDATE') + '.'] },
    kAnder: { t: 'Other complaint on the same order', wat: 'Complaints in the selection on an order that already had an earlier complaint, but about a different (or unknown) problem. They are not follow-ups and form a case of their own.', bron: ['Calculated in the tool; see the “Follow-up” filter.'] },
    kInterv: { t: 'With intervention', wat: 'The number of complaints in the selection with action “Intervention”, and their share of all complaints in the selection.', bron: [C('KLEVPL') + ' = 4 in ' + S + '.'] },
    kVervolg: { t: 'Follow-up complaints', wat: 'The number of complaints in the selection that follow up an earlier complaint in the same case (within 1 year), and their share.', bron: ['Calculated in the tool; see the “Follow-up” filter.'], let: 'Recent complaints may still get a follow-up later; the share for the last months will therefore still rise.' },
    zoek: { t: 'Search', wat: 'Searches the text entered (case-insensitive, also in the middle of a word) in the free text of the complaint.', bron: [C('KOPM') + ' (complaint description) and ' + C('KOPL') + ' (expected solution) in ' + S + '.', 'Cause, corrective measure and corrective action from ' + C('OORDLIB.PFKLACHTBH') + ' (' + C('BOORZA') + ', ' + C('BCORRI') + ', ' + C('BCORRE') + ').'], let: 'Complaints are entered in Dutch, French, German or English: also search for the Dutch or French term (e.g. “motor” and “moteur”).' },
    kTotal: { t: 'Complaints', wat: 'The number of complaints that meet all filters. Each complaint counts once, even with several TREE paths.', bron: ['Number of unique complaint numbers ' + C('KVOLGN') + ' in ' + S + '.'] },
    kOpen: { t: 'Open', wat: 'The number of complaints in the selection with an open status (see “Open / closed”).', bron: ['Derived from ' + C('KFASE') + ' in ' + S + '.'] },
    kCost: { t: 'NTR cost (material + installation)', wat: 'The sum of the costs booked on the complaints: the material amount plus the installation amount, in euros.', bron: [C('KNBDRB') + ' (“error amount”, material) + ' + C('KNWPL') + ' (“installation amount”) in ' + S + '.', 'These are the amounts of the confirmed NTR booking (the same amounts are in ' + C('OORDLIB.PFKLACHTNT') + ' per booking).'], let: 'Amounts are excluding VAT. Amounts above €100,000 or negative amounts are ignored: they are input errors (e.g. an order number typed into the amount field).' },
    kLead: { t: 'Average lead time to closure', wat: 'For the closed complaints in the selection: the average number of calendar days between creating and closing the complaint. Open complaints are not counted.', bron: [C('KDATA') + ' (“6. complaint closed”) − ' + C('KDATE') + ' (date logged), both in ' + S + '.'], let: 'A few complaints with a very long lead time can strongly affect the average.' },
    kTree: { t: 'With TREE filled in', wat: 'The share of complaints in the selection that have at least one TREE path.', bron: ['Complaints with at least one row in ' + C('OORDLIB.PFKLACHTT') + '.'], let: 'The lower this percentage, the less representative the TREE charts and lists are.' },
    evolutie: { t: 'Trend', wat: 'The number of complaints (or the NTR cost) per month, quarter or year, by complaint date. All filters are applied.', bron: ['Period: ' + C('KDATE') + ' in ' + S + '.', 'NTR cost: see the key figures.'], let: 'The last period is usually not complete yet and is therefore lower.' },
    mode: { t: 'Chart: timeline or years cumulative', wat: '<b>Timeline</b>: the chosen period from left to right, with the number (or cost) per month, quarter or year.<br><b>Intervention &amp; follow-up</b>: per period, the share of complaints with an intervention and the share of follow-up complaints.<br><b>Years cumulative</b>: one line per year, January to December, each week (or month) added to the previous one. You see at a glance whether a year rises faster or slower than previous years.', bron: ['Complaint date: ' + C('KDATE') + ' in ' + S + '.'], let: 'In “Years cumulative” the period filter is ignored (all other filters apply), as each year is shown in full. The current year stops at the latest complaint. Weeks count from 1 January (days 1–7 = week 1); these are not ISO weeks. The ticks below the chart choose which years are shown; your choice is remembered in this browser.' },
    target: { t: 'Target current year', wat: 'Draws a dotted target line for the current year: last year’s cumulative curve reduced by the chosen percentage. If this year’s complaints stay below that line, you are on track.', bron: ['Calculated from last year’s line in the same selection.'] },
    split: { t: 'Split by', wat: 'Shows one line per value instead of one total. The 7 largest values get their own line; the rest is added up in “Other”.', bron: ['The same fields as the filters with the same name.'], let: 'For TREE, complaints without TREE do not count, and a complaint with several paths counts in each path.' },
    top: { t: 'Where are the complaints?', wat: 'The most frequent TREE branches, products, NTR codes and customers in the current selection. The percentage is the share of the total number of complaints in the selection. Click a bar to filter on it.', bron: ['TREE: ' + C('OORDLIB.PFKLACHTT') + '. Products, NTR codes and customers: see the filters.'], let: 'For TREE, a complaint can appear in several branches; the percentages can then add up to more than 100%.' },
    lijst: { t: 'Complaints', wat: 'The complaints in the selection, newest first. Click a column title to sort, and a complaint for all details. “Export to Excel” gives the whole selection (not just the page shown).', bron: ['Detail from ' + S + ': order (' + C('KORNR') + '), NTR order (' + C('KNORDER') + '), handled by (' + C('KBEHA') + '), dates per phase: in progress (' + C('KDATB') + '), in warehouse (' + C('KDATM') + '), at installation service (' + C('KDATD') + '), solved for customer (' + C('KDATK') + '), closed (' + C('KDATA') + ').', 'Cause and measures: ' + C('OORDLIB.PFKLACHTBH') + '.', '“Open in WinPro” opens the complaint in WinPro (only on the Winsol network).'] },
  },

  /* ═══════════════════════════ DEUTSCH ═══════════════════════════ */
  de: {
    filters: { t: 'Filter', wat: 'Alle Filter wirken zusammen (UND): Eine Reklamation muss jeden gesetzten Filter erfüllen. Innerhalb eines Filters mit Mehrfachauswahl genügt eine der Optionen (ODER). Die Zahlen in den Listen beziehen sich auf alle geladenen Reklamationen, nicht nur auf die aktuelle Auswahl.', bron: ['Eine Zeile pro Reklamation in ' + S + ' (Reklamationsmodul von WinPro auf der AS400).', 'Nur Reklamationen ab dem 1.1.2020 werden geladen (' + C('KDATJJ &gt;= 2020') + ').'] },
    periode: { t: 'Zeitraum (Reklamationsdatum)', wat: 'Zeigt Reklamationen, deren Erstellungsdatum zwischen den beiden Daten liegt (einschließlich). Die Schnellauswahl rechnet ab der jüngsten Reklamation zurück.', bron: [C('KDATE') + ' in ' + S + ': „Erfassungsdatum“, der Tag, an dem die Reklamation angelegt wurde (Format JJJJMMTT).'], let: 'Dies ist das Datum der Reklamation, nicht das der Lieferung oder Produktion.' },
    pg: { t: 'Produktgruppe', wat: 'Die auf der Reklamation angegebene Produktgruppe, z. B. SO!, Markisen, Screens, Rollläden, PVC-Fenster. Die Schaltflächen Winsol, WinVista und WinBalu unten in der Liste wählen mit einem Klick eine feste Gruppe von Produktgruppen.', bron: ['Code: ' + C('KPROD') + ' in ' + S + ' (z. B. 4S, 4A, 2A).', 'Beschreibung: ' + C('WINSOLPRO.PFPRODGRO') + ' (' + C('KO_PG') + ' → ' + C('OMS_PGN') + ').'], let: 'Auf der AS400 steht „|“, wo die Marke „!“ schreibt; das Tool zeigt SO! und Z!P. Die Namen der Produktgruppen stammen aus der AS400 und bleiben auf Niederländisch.' },
    prod: { t: 'Produkt', wat: 'Das Produkt (Artikel), auf das sich die Reklamation bezieht, z. B. SO!Classic, Squaro, Solarfix.', bron: ['Code: ' + C('KARTNR') + ' in ' + S + ' (Artikelnummer, 3 Ziffern).', 'Name: ' + C('OARTLIB.PFPROD') + ' (' + C('PROD') + ' → ' + C('PRODBN') + ', niederländische Bezeichnung).'], let: 'Reklamationen über den Webshop oder zu Einzelteilen stehen oft auf einem Sammelprodukt wie „WEBSHOP ARTIKEL HELIOS“. Das eigentliche Produkt ist dann unbekannt; nutzen Sie TREE oder die Beschreibung.' },
    tree: { t: 'TREE (Defekt)', wat: 'Der in WinPro ausgefüllte Auswahlbaum (Registerkarte „Tree“ der Reklamation): Produkt › Art des Problems › Bauteil › Detail, z. B. SO! › WERKING › SENSOREN › Sensor defect › Temperatuursensor. Bei Auswahl einer höheren Ebene sind alle darunterliegenden Zweige enthalten.', bron: [C('OORDLIB.PFKLACHTT') + ': ' + C('TVOLGN') + ' (Reklamationsnummer), ' + C('TTREEID') + ' (Zweig-ID), ' + C('TTREEOM') + ' (vollständiger Pfad als Text).', 'Diese Tabelle wird jede Nacht von WinPro auf die AS400 kopiert.'], let: 'Eine Reklamation kann mehrere TREE-Pfade haben und zählt dann in jedem Pfad. TREE wird erst seit 2024 wirklich genutzt (ca. 35–40 % der Reklamationen). Die Ebenen 1 bis 3 sind zuverlässig; alles darunter wird als ein Detailtext gezeigt. TREE-Texte bleiben auf Niederländisch.' },
    ntr: { t: 'NTR-Code', wat: 'Die NTR-Kategorie, unter der die Reklamation gebucht wurde: Ursache oder Verantwortlicher, z. B. 13 Garantie, 8 Produktion, 7 Diverses Region, 9 Auftragserfassung, 12 Versand.', bron: [C('KNNTR') + ' in ' + S + ': der bestätigte NTR-Code.', 'Gibt es noch keinen bestätigten Code, verwendet das Tool ' + C('KNTR') + ' (vermuteter NTR-Code). Im Detail steht dann „(vermutlich)“.', 'Beschreibung: ' + C('OORDLIB.PFKLACHTN') + ' (' + C('NNTR') + ' → ' + C('NOMSC') + ').'], let: '„NTR fehlt“ = weder ein bestätigter noch ein vermuteter Code. QC-Grundregel: Reklamationen ohne NTR-Code zählen in Analysen nicht mit (über diesen Filter ausschließen).' },
    fout: { t: 'Fehlercode', wat: 'Feinere Einteilung innerhalb des NTR-Codes, z. B. 1302 Garantie Winsol, 1301 Garantie Lieferant. Die ersten Ziffern verweisen auf den NTR-Code.', bron: [C('KNFOUT') + ' in ' + S + ' (bestätigt), sonst ' + C('KFOUT') + ' (vermutet).', 'Beschreibung: ' + C('OORDLIB.PFKLACHTFO') + ' und ' + C('OORDLIB.PFKLACHTF2') + ' (' + C('UFOUT') + ' → ' + C('UOMSC') + ').'], let: 'Erscheint ein Code als „Fout 904“ ohne Namen, steht er in keiner der beiden Beschreibungstabellen.' },
    klant: { t: 'Kunde', wat: 'Der Kunde, auf dessen Namen die Reklamation läuft (Händler, Schreiner, Privatkunde…). Suche nach Name oder Nummer.', bron: [C('KFIRMA') + ' + ' + C('KKLNR') + ' in ' + S + '.', 'Name und Land aus der Kundendatei der Firma: W = ' + C('WVDJ.PFKLAN') + ' (Winsol), B = ' + C('BADJ.PFKLAN') + ' (Winbalu), H = ' + C('HEDJ.PFKLAN') + ' (Helios); Felder ' + C('KNAAM1') + ', ' + C('KNAT') + '.'], let: 'Eine Kundennummer ist nur zusammen mit der Firma eindeutig. Fast alle Reklamationen stehen auf Firma W, auch die zu Helios-Produkten.' },
    status: { t: 'Status', wat: 'Die aktuelle Phase der Reklamation, z. B. in Bearbeitung, Material im Lager bereit, beim Montagedienst, abgeschlossen.', bron: ['Code: ' + C('KFASE') + ' in ' + S + '.', 'Beschreibung: ' + C('OORDLIB.PFKLACHTFA') + ' (' + C('OFASE') + ' → ' + C('OFASEOM') + ').'], let: 'Das ist der heutige Status (zum letzten Aktualisieren), nicht der Status am Reklamationsdatum. Statusnamen bleiben auf Niederländisch.' },
    vert: { t: 'Vertreter', wat: 'Der mit der Reklamation verknüpfte Vertreter. Ein Vertriebsmitarbeiter sieht nur seine eigenen Reklamationen, ein Direktor die der Vertreter seiner Region.', bron: ['Nummer: ' + C('KVTNR') + ' in ' + S + '.', 'Name: ' + C('ODIVERS.PFVERT') + ' (' + C('VERTNR') + ' → ' + C('VNAAM') + ').'] },
    regio: { t: 'Region', wat: 'Die Verkaufsregion der Reklamation.', bron: ['Nummer: ' + C('KREGIO') + ' in ' + S + '.', 'Name: ' + C('ODIVERS.PFREGIO') + ' (' + C('REGIO') + ' → ' + C('REGPNN') + ').'], let: 'Einige Regionsnummern haben keinen Namen in der Tabelle; dann wird nur die Nummer gezeigt.' },
    open: { t: 'Offen / abgeschlossen', wat: 'Eine Reklamation gilt als <b>abgeschlossen</b>, wenn ihr Status einer dieser ist: A Reklamation abgeschlossen, W Reklamation abgelehnt, I Reklamation zur Info, O Reklamation zur Info (abgeschlossen), Y Intervention abgelehnt. Alle anderen Status gelten als <b>offen</b>.', bron: ['Abgeleitet aus ' + C('KFASE') + ' in ' + S + '.'], let: 'Diese Regel ist im Tool festgelegt (nicht in der AS400). „Reklamation vom Werk abgelehnt“ (R) gilt als offen, wie im Reporting des Controllings.' },
    terinfo: { t: 'Reklamationen „zur Info“', wat: 'Reklamationen mit Status I (Reklamation zur Info) oder O (Reklamation zur Info, abgeschlossen) sind Meldungen ohne echte Bearbeitung. Standardmäßig zählen sie nicht mit, wie im Reklamationsreporting des Controllings.', bron: ['Abgeleitet aus ' + C('KFASE') + ' in ' + S + '.'] },
    actie: { t: 'Durchzuführende Aktion', wat: 'Die Auswahl „Durchzuführende Aktion?“ der Reklamation in WinPro: was zur Lösung getan werden muss. Eine Reklamation mit Aktion <b>Intervention</b> zählt als Intervention: Jemand fährt zur Reparatur vor Ort. <b>Montieren</b> ist ebenfalls vor Ort, aber um neues Material zu montieren.', bron: [C('KLEVPL') + ' in ' + S + ': 1 Liefern, 2 Montieren, 3 Abholen, 4 Intervention, 5 Zur Info, 0 nicht ausgefüllt.'], let: 'Das (I) neben der Reklamationsnummer in WinPro (Feld ' + C('IINTVEN') + ', 1 = intern, I = über Extranet) bedeutet „Intervention angefragt“ und steht als Zusatzinfo im Detail. Für die Zahlen zählt die Aktion.' },
    vervolg: { t: 'Folge', wat: 'Ein <b>Vorgang</b> ist ein Problem. Eine <b>Folgereklamation</b> ist eine weitere Reklamation zum selben Problem innerhalb 1 Jahres nach der vorigen: Das Problem wurde also nicht auf einmal gelöst. Das ist der Fall, wenn die Reklamation (1) auf dem Reparaturauftrag (NTR-Auftrag) einer früheren Reklamation steht oder (2) auf demselben Auftrag mit demselben TREE (Ebene 3). Eine <b>andere Reklamation zum selben Auftrag</b> ist ein neues Problem auf einem Auftrag, der schon eine Reklamation hatte: ein eigener Vorgang.', bron: ['Auftrag der Reklamation: ' + C('KORNR') + '; Reparaturauftrag: ' + C('KNORDER') + '; Reihenfolge: ' + C('KDATE') + ', in ' + S + '.', 'Thema: TREE Ebene 3 aus ' + C('OORDLIB.PFKLACHTT') + '.'], let: 'Ohne TREE ist das Thema unbekannt; eine solche Reklamation zum selben Auftrag zählt vorsichtshalber als „andere Reklamation“. Kurze Auftragsnummern (1, 12, 43…) sind Regionsnummern, keine Aufträge. Folgen werden über alle Reklamationen berechnet, auch außerhalb der aktuellen Filter.' },
    kDos: { t: 'Vorgänge', wat: 'Die Anzahl verschiedener Vorgänge (eindeutige Probleme), zu denen die Reklamationen der Auswahl gehören. Siehe den Filter „Folge“.', bron: ['Im Tool berechnet aus ' + C('KORNR') + ', ' + C('KNORDER') + ' und ' + C('KDATE') + '.'] },
    kAnder: { t: 'Andere Reklamation zum selben Auftrag', wat: 'Reklamationen der Auswahl zu einem Auftrag, der schon eine frühere Reklamation hatte, aber zu einem anderen (oder unbekannten) Problem. Sie sind keine Folgereklamation und bilden einen eigenen Vorgang.', bron: ['Im Tool berechnet; siehe den Filter „Folge“.'] },
    kInterv: { t: 'Mit Intervention', wat: 'Die Anzahl der Reklamationen der Auswahl mit Aktion „Intervention“ und ihr Anteil an allen Reklamationen der Auswahl.', bron: [C('KLEVPL') + ' = 4 in ' + S + '.'] },
    kVervolg: { t: 'Folgereklamationen', wat: 'Die Anzahl der Reklamationen der Auswahl, die eine Folge einer früheren Reklamation im selben Vorgang sind (innerhalb 1 Jahres), und ihr Anteil.', bron: ['Im Tool berechnet; siehe den Filter „Folge“.'], let: 'Neuere Reklamationen können später noch eine Folge bekommen; der Anteil der letzten Monate steigt daher noch.' },
    zoek: { t: 'Suchbegriff', wat: 'Sucht den eingegebenen Text (ohne Groß-/Kleinschreibung, auch mitten im Wort) im Freitext der Reklamation.', bron: [C('KOPM') + ' (Beschreibung) und ' + C('KOPL') + ' (erwartete Lösung) in ' + S + '.', 'Ursache, Korrekturmaßnahme und korrigierende Maßnahme aus ' + C('OORDLIB.PFKLACHTBH') + ' (' + C('BOORZA') + ', ' + C('BCORRI') + ', ' + C('BCORRE') + ').'], let: 'Reklamationen werden auf Niederländisch, Französisch, Deutsch oder Englisch erfasst: suchen Sie auch nach dem niederländischen oder französischen Begriff (z. B. „motor“ und „moteur“).' },
    kTotal: { t: 'Reklamationen', wat: 'Die Anzahl der Reklamationen, die alle Filter erfüllen. Jede Reklamation zählt einmal, auch mit mehreren TREE-Pfaden.', bron: ['Anzahl eindeutiger Reklamationsnummern ' + C('KVOLGN') + ' in ' + S + '.'] },
    kOpen: { t: 'Offen', wat: 'Die Anzahl der Reklamationen der Auswahl mit offenem Status (siehe „Offen / abgeschlossen“).', bron: ['Abgeleitet aus ' + C('KFASE') + ' in ' + S + '.'] },
    kCost: { t: 'NTR-Kosten (Material + Montage)', wat: 'Die Summe der auf die Reklamationen gebuchten Kosten: Materialbetrag plus Montagebetrag, in Euro.', bron: [C('KNBDRB') + ' („Fehlerbetrag“, Material) + ' + C('KNWPL') + ' („Montagebetrag“) in ' + S + '.', 'Das sind die Beträge der bestätigten NTR-Buchung (dieselben Beträge stehen pro Buchung in ' + C('OORDLIB.PFKLACHTNT') + ').'], let: 'Die Beträge verstehen sich ohne MwSt. Beträge über 100.000 € oder negative Beträge zählen nicht: Das sind Eingabefehler (z. B. eine Auftragsnummer im Betragsfeld).' },
    kLead: { t: 'Durchschnittliche Durchlaufzeit bis Abschluss', wat: 'Für die abgeschlossenen Reklamationen der Auswahl: die durchschnittliche Anzahl Kalendertage zwischen Anlage und Abschluss. Offene Reklamationen zählen nicht.', bron: [C('KDATA') + ' („6. Reklamation abgeschlossen“) − ' + C('KDATE') + ' (Erfassungsdatum), beide in ' + S + '.'], let: 'Einige Reklamationen mit sehr langer Durchlaufzeit können den Durchschnitt stark beeinflussen.' },
    kTree: { t: 'Mit TREE ausgefüllt', wat: 'Der Anteil der Reklamationen der Auswahl mit mindestens einem TREE-Pfad.', bron: ['Reklamationen mit mindestens einer Zeile in ' + C('OORDLIB.PFKLACHTT') + '.'], let: 'Je niedriger dieser Prozentsatz, desto weniger repräsentativ sind die TREE-Grafiken und -Listen.' },
    evolutie: { t: 'Entwicklung', wat: 'Die Anzahl der Reklamationen (oder die NTR-Kosten) pro Monat, Quartal oder Jahr nach Reklamationsdatum. Alle Filter sind angewendet.', bron: ['Zeitraum: ' + C('KDATE') + ' in ' + S + '.', 'NTR-Kosten: siehe Kennzahlen.'], let: 'Der letzte Zeitraum ist meist noch nicht vollständig und liegt daher niedriger.' },
    mode: { t: 'Diagramm: Zeitachse oder Jahre kumuliert', wat: '<b>Zeitachse</b>: der gewählte Zeitraum von links nach rechts mit der Anzahl (oder den Kosten) pro Monat, Quartal oder Jahr.<br><b>Intervention &amp; Folge</b>: pro Zeitraum der Anteil der Reklamationen mit Intervention und der Anteil der Folgereklamationen.<br><b>Jahre kumuliert</b>: eine Linie pro Jahr von Januar bis Dezember, wobei jede Woche (oder jeder Monat) zur vorigen addiert wird. So sehen Sie auf einen Blick, ob ein Jahr schneller oder langsamer ansteigt als die Vorjahre.', bron: ['Reklamationsdatum: ' + C('KDATE') + ' in ' + S + '.'], let: 'In „Jahre kumuliert“ wird der Zeitraumfilter ignoriert (alle anderen Filter gelten). Das laufende Jahr endet bei der letzten Reklamation. Wochen zählen ab dem 1. Januar (Tag 1–7 = Woche 1); das sind keine ISO-Wochen. Mit den Häkchen unter dem Diagramm wählen Sie die angezeigten Jahre; Ihre Auswahl wird in diesem Browser gespeichert.' },
    target: { t: 'Ziel laufendes Jahr', wat: 'Zeichnet eine gestrichelte Ziellinie für das laufende Jahr: die kumulierte Kurve des Vorjahres, reduziert um den gewählten Prozentsatz. Bleiben die Reklamationen dieses Jahres unter dieser Linie, sind Sie auf Kurs.', bron: ['Berechnet aus der Vorjahreslinie in derselben Auswahl.'] },
    split: { t: 'Aufteilen nach', wat: 'Zeigt eine Linie pro Wert statt einer Gesamtsumme. Die 7 größten Werte erhalten eine eigene Linie, der Rest wird unter „Sonstige“ zusammengefasst.', bron: ['Dieselben Felder wie die gleichnamigen Filter.'], let: 'Bei TREE zählen Reklamationen ohne TREE nicht, und eine Reklamation mit mehreren Pfaden zählt in jedem Pfad.' },
    top: { t: 'Wo liegen die Reklamationen?', wat: 'Die häufigsten TREE-Zweige, Produkte, NTR-Codes und Kunden in der aktuellen Auswahl. Der Prozentsatz ist der Anteil an allen Reklamationen der Auswahl. Klicken Sie auf einen Balken, um danach zu filtern.', bron: ['TREE: ' + C('OORDLIB.PFKLACHTT') + '. Produkte, NTR-Codes und Kunden: siehe Filter.'], let: 'Bei TREE kann eine Reklamation in mehreren Zweigen vorkommen; die Prozentsätze können dann zusammen über 100 % ergeben.' },
    lijst: { t: 'Reklamationen', wat: 'Die Reklamationen der Auswahl, die jüngsten zuerst. Klicken Sie auf einen Spaltentitel zum Sortieren und auf eine Reklamation für alle Details. „Nach Excel exportieren“ liefert die gesamte Auswahl (nicht nur die angezeigte Seite).', bron: ['Detail aus ' + S + ': Auftrag (' + C('KORNR') + '), NTR-Auftrag (' + C('KNORDER') + '), bearbeitet von (' + C('KBEHA') + '), Daten pro Phase: in Bearbeitung (' + C('KDATB') + '), im Lager (' + C('KDATM') + '), beim Montagedienst (' + C('KDATD') + '), für Kunden gelöst (' + C('KDATK') + '), abgeschlossen (' + C('KDATA') + ').', 'Ursache und Maßnahmen: ' + C('OORDLIB.PFKLACHTBH') + '.', '„In WinPro öffnen“ öffnet die Reklamation in WinPro (nur im Winsol-Netzwerk).'] },
  },

  /* ═══════════════════════════ ESPAÑOL ═══════════════════════════ */
  es: {
    filters: { t: 'Filtros', wat: 'Todos los filtros se combinan (Y): una reclamación debe cumplir cada filtro rellenado. Dentro de un filtro de selección múltiple basta con una de las opciones (O). Los números de las listas cuentan todas las reclamaciones cargadas, no solo la selección actual.', bron: ['Una fila por reclamación en ' + S + ' (módulo de reclamaciones de WinPro, en el AS400).', 'Solo se cargan las reclamaciones a partir del 1/1/2020 (' + C('KDATJJ &gt;= 2020') + ').'] },
    periode: { t: 'Periodo (fecha de la reclamación)', wat: 'Muestra las reclamaciones cuya fecha de creación está entre las dos fechas (incluidas). Los accesos rápidos cuentan hacia atrás desde la reclamación más reciente.', bron: [C('KDATE') + ' en ' + S + ': «fecha de registro», el día en que se creó la reclamación (formato AAAAMMDD).'], let: 'Es la fecha de la reclamación, no la de entrega o producción del producto.' },
    pg: { t: 'Grupo de productos', wat: 'El grupo de productos indicado en la reclamación, p. ej. SO!, Toldos, Screens, Persianas, Ventanas de PVC. Los botones Winsol, WinVista y WinBalu al pie de la lista marcan de un clic un conjunto fijo de grupos.', bron: ['Código: ' + C('KPROD') + ' en ' + S + ' (p. ej. 4S, 4A, 2A).', 'Descripción: ' + C('WINSOLPRO.PFPRODGRO') + ' (' + C('KO_PG') + ' → ' + C('OMS_PGN') + ').'], let: 'En el AS400 aparece «|» donde la marca escribe «!»; la herramienta muestra SO! y Z!P. Los nombres de los grupos proceden del AS400 y se mantienen en neerlandés.' },
    prod: { t: 'Producto', wat: 'El producto (artículo) al que se refiere la reclamación, p. ej. SO!Classic, Squaro, Solarfix.', bron: ['Código: ' + C('KARTNR') + ' en ' + S + ' (número de artículo, 3 cifras).', 'Nombre: ' + C('OARTLIB.PFPROD') + ' (' + C('PROD') + ' → ' + C('PRODBN') + ', denominación neerlandesa).'], let: 'Las reclamaciones por la tienda web o sobre piezas sueltas suelen estar en un producto genérico como «WEBSHOP ARTIKEL HELIOS». El producto real es entonces desconocido; use TREE o la descripción.' },
    tree: { t: 'TREE (defecto)', wat: 'El árbol de selección rellenado en WinPro (pestaña «Tree» de la reclamación): producto › tipo de problema › componente › detalle, p. ej. SO! › WERKING › SENSOREN › Sensor defect › Temperatuursensor. Si elige un nivel superior, se incluyen todas las ramas inferiores.', bron: [C('OORDLIB.PFKLACHTT') + ': ' + C('TVOLGN') + ' (número de reclamación), ' + C('TTREEID') + ' (id de la rama), ' + C('TTREEOM') + ' (ruta completa en texto).', 'Esta tabla se copia cada noche de WinPro al AS400.'], let: 'Una reclamación puede tener varias rutas TREE y entonces cuenta en cada una. TREE solo se usa de verdad desde 2024 (aprox. 35–40 % de las reclamaciones). Los niveles 1 a 3 son fiables; el resto se muestra como un único texto de detalle. Los textos TREE se mantienen en neerlandés.' },
    ntr: { t: 'Código NTR', wat: 'La categoría NTR con la que se registró la reclamación: la causa o el responsable, p. ej. 13 Garantía, 8 Producción, 7 Varios región, 9 Registro de pedidos, 12 Expedición.', bron: [C('KNNTR') + ' en ' + S + ': el código NTR confirmado.', 'Si aún no hay código confirmado, la herramienta usa ' + C('KNTR') + ' (código NTR presunto). El detalle indica entonces «(presunto)».', 'Descripción: ' + C('OORDLIB.PFKLACHTN') + ' (' + C('NNTR') + ' → ' + C('NOMSC') + ').'], let: '«Falta NTR» = ni código confirmado ni presunto. Regla básica de QC: las reclamaciones sin código NTR no cuentan en los análisis (exclúyalas con este filtro).' },
    fout: { t: 'Código de error', wat: 'Subdivisión más fina del código NTR, p. ej. 1302 Garantía Winsol, 1301 Garantía proveedor. Las primeras cifras remiten al código NTR.', bron: [C('KNFOUT') + ' en ' + S + ' (confirmado), si no ' + C('KFOUT') + ' (presunto).', 'Descripción: ' + C('OORDLIB.PFKLACHTFO') + ' y ' + C('OORDLIB.PFKLACHTF2') + ' (' + C('UFOUT') + ' → ' + C('UOMSC') + ').'], let: 'Si un código aparece como «Fout 904» sin nombre, no figura en ninguna de las dos tablas de descripción.' },
    klant: { t: 'Cliente', wat: 'El cliente a cuyo nombre está la reclamación (distribuidor, carpintero, particular…). Se puede buscar por nombre o número.', bron: [C('KFIRMA') + ' + ' + C('KKLNR') + ' en ' + S + '.', 'Nombre y país del fichero de clientes de la empresa: W = ' + C('WVDJ.PFKLAN') + ' (Winsol), B = ' + C('BADJ.PFKLAN') + ' (Winbalu), H = ' + C('HEDJ.PFKLAN') + ' (Helios); campos ' + C('KNAAM1') + ', ' + C('KNAT') + '.'], let: 'Un número de cliente solo es único junto con la empresa. Casi todas las reclamaciones están en la empresa W, también las de productos Helios.' },
    status: { t: 'Estado', wat: 'La fase actual de la reclamación, p. ej. en tramitación, material listo en almacén, en el servicio de instalación, cerrada.', bron: ['Código: ' + C('KFASE') + ' en ' + S + '.', 'Descripción: ' + C('OORDLIB.PFKLACHTFA') + ' (' + C('OFASE') + ' → ' + C('OFASEOM') + ').'], let: 'Es el estado de hoy (en la última actualización), no el estado en la fecha de la reclamación. Los nombres de estado se mantienen en neerlandés.' },
    vert: { t: 'Representante', wat: 'El representante vinculado a la reclamación. Un comercial solo ve sus propias reclamaciones; un director, las de los comerciales de su región.', bron: ['Número: ' + C('KVTNR') + ' en ' + S + '.', 'Nombre: ' + C('ODIVERS.PFVERT') + ' (' + C('VERTNR') + ' → ' + C('VNAAM') + ').'] },
    regio: { t: 'Región', wat: 'La región de ventas de la reclamación.', bron: ['Número: ' + C('KREGIO') + ' en ' + S + '.', 'Nombre: ' + C('ODIVERS.PFREGIO') + ' (' + C('REGIO') + ' → ' + C('REGPNN') + ').'], let: 'Algunos números de región no tienen nombre en la tabla; solo se muestra el número.' },
    open: { t: 'Abierta / cerrada', wat: 'Una reclamación cuenta como <b>cerrada</b> si su estado es uno de estos: A Reclamación cerrada, W Reclamación rechazada, I Reclamación para información, O Reclamación para información (cerrada), Y Intervención rechazada. Todos los demás estados cuentan como <b>abiertos</b>.', bron: ['Derivado de ' + C('KFASE') + ' en ' + S + '.'], let: 'Esta regla está fijada en la herramienta (no en el AS400). «Reclamación rechazada por fábrica» (R) cuenta como abierta, como en el informe de Controlling.' },
    terinfo: { t: 'Reclamaciones «para información»', wat: 'Las reclamaciones con estado I (para información) u O (para información, cerrada) son avisos sin tramitación real. Por defecto no cuentan, como en el informe de reclamaciones de Controlling.', bron: ['Derivado de ' + C('KFASE') + ' en ' + S + '.'] },
    actie: { t: 'Acción a realizar', wat: 'La opción «¿Acción a realizar?» de la reclamación en WinPro: lo que hay que hacer para resolverla. Una reclamación con acción <b>Intervención</b> cuenta como intervención: alguien acude al lugar para reparar. <b>Instalar</b> también es in situ, pero para instalar material nuevo.', bron: [C('KLEVPL') + ' en ' + S + ': 1 Entregar, 2 Instalar, 3 Recoger, 4 Intervención, 5 Para información, 0 sin rellenar.'], let: 'La (I) junto al número de reclamación en WinPro (campo ' + C('IINTVEN') + ', 1 = interno, I = vía Extranet) significa «intervención solicitada» y aparece como información adicional en el detalle. Para las cifras cuenta la acción.' },
    vervolg: { t: 'Seguimiento', wat: 'Un <b>expediente</b> es un problema. Una <b>reclamación de seguimiento</b> es una nueva reclamación sobre el mismo problema dentro de 1 año tras la anterior: el problema no se resolvió de una vez. Es así si la reclamación (1) está en el pedido de reparación (pedido NTR) de una reclamación anterior, o (2) está en el mismo pedido con el mismo TREE (nivel 3). Una <b>otra reclamación en el mismo pedido</b> es un problema nuevo en un pedido que ya tenía una reclamación: un expediente propio.', bron: ['Pedido de la reclamación: ' + C('KORNR') + '; pedido de reparación: ' + C('KNORDER') + '; orden: ' + C('KDATE') + ', en ' + S + '.', 'Tema: TREE nivel 3 de ' + C('OORDLIB.PFKLACHTT') + '.'], let: 'Sin TREE el tema es desconocido; esa reclamación en el mismo pedido cuenta con prudencia como «otra reclamación». Los números cortos (1, 12, 43…) son números de región, no pedidos. El seguimiento se calcula sobre todas las reclamaciones, también fuera de los filtros actuales.' },
    kDos: { t: 'Expedientes', wat: 'El número de expedientes distintos (problemas únicos) a los que pertenecen las reclamaciones de la selección. Véase el filtro «Seguimiento».', bron: ['Calculado en la herramienta a partir de ' + C('KORNR') + ', ' + C('KNORDER') + ' y ' + C('KDATE') + '.'] },
    kAnder: { t: 'Otra reclamación en el mismo pedido', wat: 'Reclamaciones de la selección en un pedido que ya tenía una reclamación anterior, pero sobre otro problema (o desconocido). No son de seguimiento y forman su propio expediente.', bron: ['Calculado en la herramienta; véase el filtro «Seguimiento».'] },
    kInterv: { t: 'Con intervención', wat: 'El número de reclamaciones de la selección con acción «Intervención» y su proporción en el total de la selección.', bron: [C('KLEVPL') + ' = 4 en ' + S + '.'] },
    kVervolg: { t: 'Reclamaciones de seguimiento', wat: 'El número de reclamaciones de la selección que son seguimiento de una reclamación anterior del mismo expediente (dentro de 1 año), y su proporción.', bron: ['Calculado en la herramienta; véase el filtro «Seguimiento».'], let: 'Las reclamaciones recientes aún pueden tener seguimiento; la proporción de los últimos meses todavía subirá.' },
    zoek: { t: 'Búsqueda', wat: 'Busca el texto introducido (sin distinguir mayúsculas, también en medio de una palabra) en el texto libre de la reclamación.', bron: [C('KOPM') + ' (descripción) y ' + C('KOPL') + ' (solución esperada) en ' + S + '.', 'Causa, medida correctora y acción correctiva de ' + C('OORDLIB.PFKLACHTBH') + ' (' + C('BOORZA') + ', ' + C('BCORRI') + ', ' + C('BCORRE') + ').'], let: 'Las reclamaciones se introducen en neerlandés, francés, alemán o inglés: busque también el término neerlandés o francés (p. ej. «motor» y «moteur»).' },
    kTotal: { t: 'Reclamaciones', wat: 'El número de reclamaciones que cumplen todos los filtros. Cada reclamación cuenta una vez, aunque tenga varias rutas TREE.', bron: ['Número de reclamaciones únicas ' + C('KVOLGN') + ' en ' + S + '.'] },
    kOpen: { t: 'Abiertas', wat: 'El número de reclamaciones de la selección con estado abierto (véase «Abierta / cerrada»).', bron: ['Derivado de ' + C('KFASE') + ' en ' + S + '.'] },
    kCost: { t: 'Coste NTR (material + instalación)', wat: 'La suma de los costes registrados en las reclamaciones: el importe de material más el de instalación, en euros.', bron: [C('KNBDRB') + ' («importe error», material) + ' + C('KNWPL') + ' («importe de instalación») en ' + S + '.', 'Son los importes del registro NTR confirmado (los mismos importes figuran por registro en ' + C('OORDLIB.PFKLACHTNT') + ').'], let: 'Los importes son sin IVA. Los importes superiores a 100 000 € o negativos no cuentan: son errores de entrada (p. ej. un número de pedido tecleado en el campo del importe).' },
    kLead: { t: 'Plazo medio hasta el cierre', wat: 'Para las reclamaciones cerradas de la selección: el número medio de días naturales entre la creación y el cierre. Las abiertas no cuentan.', bron: [C('KDATA') + ' («6. reclamación cerrada») − ' + C('KDATE') + ' (fecha de registro), ambos en ' + S + '.'], let: 'Unas pocas reclamaciones con un plazo muy largo pueden influir mucho en la media.' },
    kTree: { t: 'Con TREE rellenado', wat: 'La proporción de reclamaciones de la selección con al menos una ruta TREE.', bron: ['Reclamaciones con al menos una fila en ' + C('OORDLIB.PFKLACHTT') + '.'], let: 'Cuanto menor sea este porcentaje, menos representativos son los gráficos y listas TREE.' },
    evolutie: { t: 'Evolución', wat: 'El número de reclamaciones (o el coste NTR) por mes, trimestre o año, según la fecha de la reclamación. Se aplican todos los filtros.', bron: ['Periodo: ' + C('KDATE') + ' en ' + S + '.', 'Coste NTR: véanse las cifras clave.'], let: 'El último periodo suele no estar completo todavía y por eso es más bajo.' },
    mode: { t: 'Gráfico: línea de tiempo o años acumulados', wat: '<b>Línea de tiempo</b>: el periodo elegido de izquierda a derecha, con el número (o el coste) por mes, trimestre o año.<br><b>Intervención y seguimiento</b>: por periodo, la proporción de reclamaciones con intervención y la de reclamaciones de seguimiento.<br><b>Años acumulados</b>: una línea por año, de enero a diciembre, sumando cada semana (o mes) a la anterior. Así se ve de un vistazo si un año crece más rápido o más despacio que los anteriores.', bron: ['Fecha de la reclamación: ' + C('KDATE') + ' en ' + S + '.'], let: 'En «Años acumulados» se ignora el filtro de periodo (los demás se aplican). El año en curso se detiene en la última reclamación. Las semanas cuentan desde el 1 de enero (días 1–7 = semana 1); no son semanas ISO. Las casillas bajo el gráfico eligen los años mostrados; su elección se recuerda en este navegador.' },
    target: { t: 'Objetivo del año en curso', wat: 'Dibuja una línea de objetivo discontinua para el año en curso: la curva acumulada del año anterior reducida en el porcentaje elegido. Si las reclamaciones de este año quedan por debajo, va por buen camino.', bron: ['Calculado a partir de la línea del año anterior en la misma selección.'] },
    split: { t: 'Desglosar por', wat: 'Muestra una línea por valor en lugar de un total. Los 7 valores mayores tienen línea propia; el resto se agrupa en «Otros».', bron: ['Los mismos campos que los filtros del mismo nombre.'], let: 'En TREE, las reclamaciones sin TREE no cuentan y una reclamación con varias rutas cuenta en cada una.' },
    top: { t: '¿Dónde están las reclamaciones?', wat: 'Las ramas TREE, productos, códigos NTR y clientes más frecuentes en la selección actual. El porcentaje es la proporción del total de reclamaciones de la selección. Haga clic en una barra para filtrar.', bron: ['TREE: ' + C('OORDLIB.PFKLACHTT') + '. Productos, códigos NTR y clientes: véanse los filtros.'], let: 'En TREE una reclamación puede aparecer en varias ramas; los porcentajes pueden sumar más del 100 %.' },
    lijst: { t: 'Reclamaciones', wat: 'Las reclamaciones de la selección, las más recientes primero. Haga clic en el título de una columna para ordenar y en una reclamación para ver todos los detalles. «Exportar a Excel» da toda la selección (no solo la página mostrada).', bron: ['Detalle de ' + S + ': pedido (' + C('KORNR') + '), pedido NTR (' + C('KNORDER') + '), tramitado por (' + C('KBEHA') + '), fechas por fase: en tramitación (' + C('KDATB') + '), en almacén (' + C('KDATM') + '), en el servicio de instalación (' + C('KDATD') + '), resuelta para el cliente (' + C('KDATK') + '), cerrada (' + C('KDATA') + ').', 'Causa y medidas: ' + C('OORDLIB.PFKLACHTBH') + '.', '«Abrir en WinPro» abre la reclamación en WinPro (solo en la red de Winsol).'] },
  },

  /* ═══════════════════════════ ITALIANO ═══════════════════════════ */
  it: {
    filters: { t: 'Filtri', wat: 'Tutti i filtri si combinano (E): un reclamo deve soddisfare ogni filtro impostato. All’interno di un filtro a scelta multipla basta una delle opzioni (O). I numeri negli elenchi contano tutti i reclami caricati, non solo la selezione attuale.', bron: ['Una riga per reclamo in ' + S + ' (modulo reclami di WinPro, sull’AS400).', 'Vengono caricati solo i reclami dal 1/1/2020 (' + C('KDATJJ &gt;= 2020') + ').'] },
    periode: { t: 'Periodo (data del reclamo)', wat: 'Mostra i reclami la cui data di creazione è compresa tra le due date (incluse). Le scelte rapide contano a ritroso dal reclamo più recente.', bron: [C('KDATE') + ' in ' + S + ': «data di registrazione», il giorno in cui il reclamo è stato creato (formato AAAAMMGG).'], let: 'È la data del reclamo, non della consegna o produzione del prodotto.' },
    pg: { t: 'Gruppo di prodotti', wat: 'Il gruppo di prodotti indicato sul reclamo, ad es. SO!, Tende da sole, Screens, Tapparelle, Finestre in PVC. I pulsanti Winsol, WinVista e WinBalu in fondo all’elenco selezionano con un clic un insieme fisso di gruppi.', bron: ['Codice: ' + C('KPROD') + ' in ' + S + ' (ad es. 4S, 4A, 2A).', 'Descrizione: ' + C('WINSOLPRO.PFPRODGRO') + ' (' + C('KO_PG') + ' → ' + C('OMS_PGN') + ').'], let: 'Sull’AS400 compare «|» dove il marchio scrive «!»; lo strumento mostra SO! e Z!P. I nomi dei gruppi provengono dall’AS400 e restano in olandese.' },
    prod: { t: 'Prodotto', wat: 'Il prodotto (articolo) a cui si riferisce il reclamo, ad es. SO!Classic, Squaro, Solarfix.', bron: ['Codice: ' + C('KARTNR') + ' in ' + S + ' (numero articolo, 3 cifre).', 'Nome: ' + C('OARTLIB.PFPROD') + ' (' + C('PROD') + ' → ' + C('PRODBN') + ', denominazione olandese).'], let: 'I reclami tramite webshop o su ricambi sono spesso su un prodotto generico come «WEBSHOP ARTIKEL HELIOS». Il prodotto reale è allora sconosciuto; usa TREE o la descrizione.' },
    tree: { t: 'TREE (difetto)', wat: 'L’albero di scelta compilato in WinPro (scheda «Tree» del reclamo): prodotto › tipo di problema › componente › dettaglio, ad es. SO! › WERKING › SENSOREN › Sensor defect › Temperatuursensor. Scegliendo un livello superiore si includono tutti i rami sottostanti.', bron: [C('OORDLIB.PFKLACHTT') + ': ' + C('TVOLGN') + ' (numero reclamo), ' + C('TTREEID') + ' (id del ramo), ' + C('TTREEOM') + ' (percorso completo come testo).', 'Questa tabella viene copiata ogni notte da WinPro all’AS400.'], let: 'Un reclamo può avere più percorsi TREE e conta allora in ciascuno. TREE è davvero usato solo dal 2024 (circa 35–40% dei reclami). I livelli da 1 a 3 sono affidabili; il resto è mostrato come un unico testo di dettaglio. I testi TREE restano in olandese.' },
    ntr: { t: 'Codice NTR', wat: 'La categoria NTR con cui il reclamo è stato registrato: la causa o il responsabile, ad es. 13 Garanzia, 8 Produzione, 7 Varie regione, 9 Inserimento ordini, 12 Spedizione.', bron: [C('KNNTR') + ' in ' + S + ': il codice NTR confermato.', 'Se non c’è ancora un codice confermato, lo strumento usa ' + C('KNTR') + ' (codice NTR presunto). Nel dettaglio compare allora «(presunto)».', 'Descrizione: ' + C('OORDLIB.PFKLACHTN') + ' (' + C('NNTR') + ' → ' + C('NOMSC') + ').'], let: '«NTR mancante» = nessun codice confermato né presunto. Regola base del QC: i reclami senza codice NTR non vengono contati nelle analisi (escludili con questo filtro).' },
    fout: { t: 'Codice errore', wat: 'Suddivisione più fine del codice NTR, ad es. 1302 Garanzia Winsol, 1301 Garanzia fornitore. Le prime cifre rimandano al codice NTR.', bron: [C('KNFOUT') + ' in ' + S + ' (confermato), altrimenti ' + C('KFOUT') + ' (presunto).', 'Descrizione: ' + C('OORDLIB.PFKLACHTFO') + ' e ' + C('OORDLIB.PFKLACHTF2') + ' (' + C('UFOUT') + ' → ' + C('UOMSC') + ').'], let: 'Se un codice appare come «Fout 904» senza nome, non è presente in nessuna delle due tabelle di descrizione.' },
    klant: { t: 'Cliente', wat: 'Il cliente a nome del quale è registrato il reclamo (rivenditore, falegname, privato…). Ricerca per nome o numero.', bron: [C('KFIRMA') + ' + ' + C('KKLNR') + ' in ' + S + '.', 'Nome e paese dall’anagrafica clienti della società: W = ' + C('WVDJ.PFKLAN') + ' (Winsol), B = ' + C('BADJ.PFKLAN') + ' (Winbalu), H = ' + C('HEDJ.PFKLAN') + ' (Helios); campi ' + C('KNAAM1') + ', ' + C('KNAT') + '.'], let: 'Un numero cliente è univoco solo insieme alla società. Quasi tutti i reclami sono sulla società W, anche quelli su prodotti Helios.' },
    status: { t: 'Stato', wat: 'La fase attuale del reclamo, ad es. in gestione, materiale pronto in magazzino, al servizio di posa, chiuso.', bron: ['Codice: ' + C('KFASE') + ' in ' + S + '.', 'Descrizione: ' + C('OORDLIB.PFKLACHTFA') + ' (' + C('OFASE') + ' → ' + C('OFASEOM') + ').'], let: 'È lo stato di oggi (all’ultimo aggiornamento), non lo stato alla data del reclamo. I nomi degli stati restano in olandese.' },
    vert: { t: 'Rappresentante', wat: 'Il rappresentante collegato al reclamo. Un commerciale vede solo i propri reclami, un direttore quelli dei commerciali della sua regione.', bron: ['Numero: ' + C('KVTNR') + ' in ' + S + '.', 'Nome: ' + C('ODIVERS.PFVERT') + ' (' + C('VERTNR') + ' → ' + C('VNAAM') + ').'] },
    regio: { t: 'Regione', wat: 'La regione di vendita del reclamo.', bron: ['Numero: ' + C('KREGIO') + ' in ' + S + '.', 'Nome: ' + C('ODIVERS.PFREGIO') + ' (' + C('REGIO') + ' → ' + C('REGPNN') + ').'], let: 'Alcuni numeri di regione non hanno nome nella tabella; viene mostrato solo il numero.' },
    open: { t: 'Aperto / chiuso', wat: 'Un reclamo conta come <b>chiuso</b> se il suo stato è uno di questi: A Reclamo chiuso, W Reclamo rifiutato, I Reclamo per info, O Reclamo per info (chiuso), Y Intervento rifiutato. Tutti gli altri stati contano come <b>aperti</b>.', bron: ['Derivato da ' + C('KFASE') + ' in ' + S + '.'], let: 'Questa regola è fissata nello strumento (non nell’AS400). «Reclamo rifiutato dalla fabbrica» (R) conta come aperto, come nel reporting del Controlling.' },
    terinfo: { t: 'Reclami «per info»', wat: 'I reclami con stato I (Reclamo per info) o O (Reclamo per info, chiuso) sono segnalazioni senza una vera gestione. Di default non vengono contati, come nel reporting reclami del Controlling.', bron: ['Derivato da ' + C('KFASE') + ' in ' + S + '.'] },
    actie: { t: 'Azione da eseguire', wat: 'La scelta «Azione da eseguire?» del reclamo in WinPro: cosa bisogna fare per risolverlo. Un reclamo con azione <b>Intervento</b> conta come intervento: qualcuno va sul posto a riparare. Anche <b>Posare</b> avviene sul posto, ma per posare nuovo materiale.', bron: [C('KLEVPL') + ' in ' + S + ': 1 Consegnare, 2 Posare, 3 Ritirare, 4 Intervento, 5 Per info, 0 non compilato.'], let: 'La (I) accanto al numero del reclamo in WinPro (campo ' + C('IINTVEN') + ', 1 = interno, I = via Extranet) significa «intervento richiesto» ed è mostrata come info aggiuntiva nel dettaglio. Per i numeri conta l’azione.' },
    vervolg: { t: 'Seguito', wat: 'Una <b>pratica</b> è un problema. Un <b>reclamo di seguito</b> è un nuovo reclamo sullo stesso problema entro 1 anno dal precedente: il problema non è stato risolto in una volta. È così se il reclamo (1) è sull’ordine di riparazione (ordine NTR) di un reclamo precedente, oppure (2) è sullo stesso ordine con lo stesso TREE (livello 3). Un <b>altro reclamo sullo stesso ordine</b> è un nuovo problema su un ordine che aveva già un reclamo: una pratica a sé.', bron: ['Ordine del reclamo: ' + C('KORNR') + '; ordine di riparazione: ' + C('KNORDER') + '; sequenza: ' + C('KDATE') + ', in ' + S + '.', 'Argomento: TREE livello 3 da ' + C('OORDLIB.PFKLACHTT') + '.'], let: 'Senza TREE l’argomento è sconosciuto; un tale reclamo sullo stesso ordine conta prudentemente come «altro reclamo». I numeri brevi (1, 12, 43…) sono numeri di regione, non ordini. Il seguito è calcolato su tutti i reclami, anche fuori dai filtri attuali.' },
    kDos: { t: 'Pratiche', wat: 'Il numero di pratiche distinte (problemi unici) a cui appartengono i reclami della selezione. Vedi il filtro «Seguito».', bron: ['Calcolato nello strumento da ' + C('KORNR') + ', ' + C('KNORDER') + ' e ' + C('KDATE') + '.'] },
    kAnder: { t: 'Altro reclamo sullo stesso ordine', wat: 'Reclami della selezione su un ordine che aveva già un reclamo precedente, ma su un problema diverso (o sconosciuto). Non sono reclami di seguito e formano una pratica a sé.', bron: ['Calcolato nello strumento; vedi il filtro «Seguito».'] },
    kInterv: { t: 'Con intervento', wat: 'Il numero di reclami della selezione con azione «Intervento» e la loro quota su tutti i reclami della selezione.', bron: [C('KLEVPL') + ' = 4 in ' + S + '.'] },
    kVervolg: { t: 'Reclami di seguito', wat: 'Il numero di reclami della selezione che sono il seguito di un reclamo precedente nella stessa pratica (entro 1 anno), e la loro quota.', bron: ['Calcolato nello strumento; vedi il filtro «Seguito».'], let: 'I reclami recenti possono ancora avere un seguito; la quota degli ultimi mesi salirà quindi ancora.' },
    zoek: { t: 'Ricerca', wat: 'Cerca il testo inserito (senza distinzione tra maiuscole e minuscole, anche a metà parola) nel testo libero del reclamo.', bron: [C('KOPM') + ' (descrizione) e ' + C('KOPL') + ' (soluzione prevista) in ' + S + '.', 'Causa, misura correttiva e azione correttiva da ' + C('OORDLIB.PFKLACHTBH') + ' (' + C('BOORZA') + ', ' + C('BCORRI') + ', ' + C('BCORRE') + ').'], let: 'I reclami vengono inseriti in olandese, francese, tedesco o inglese: cerca anche il termine olandese o francese (ad es. «motor» e «moteur»).' },
    kTotal: { t: 'Reclami', wat: 'Il numero di reclami che soddisfano tutti i filtri. Ogni reclamo conta una volta, anche con più percorsi TREE.', bron: ['Numero di reclami unici ' + C('KVOLGN') + ' in ' + S + '.'] },
    kOpen: { t: 'Aperti', wat: 'Il numero di reclami della selezione con stato aperto (vedi «Aperto / chiuso»).', bron: ['Derivato da ' + C('KFASE') + ' in ' + S + '.'] },
    kCost: { t: 'Costo NTR (materiale + posa)', wat: 'La somma dei costi registrati sui reclami: l’importo per il materiale più quello per la posa, in euro.', bron: [C('KNBDRB') + ' («importo errore», materiale) + ' + C('KNWPL') + ' («importo posa») in ' + S + '.', 'Sono gli importi della registrazione NTR confermata (gli stessi importi sono per registrazione in ' + C('OORDLIB.PFKLACHTNT') + ').'], let: 'Gli importi sono IVA esclusa. Importi superiori a 100.000 € o negativi non vengono contati: sono errori di inserimento (ad es. un numero d’ordine digitato nel campo importo).' },
    kLead: { t: 'Tempo medio fino alla chiusura', wat: 'Per i reclami chiusi della selezione: il numero medio di giorni di calendario tra creazione e chiusura. I reclami aperti non contano.', bron: [C('KDATA') + ' («6. reclamo chiuso») − ' + C('KDATE') + ' (data di registrazione), entrambi in ' + S + '.'], let: 'Pochi reclami con un tempo molto lungo possono influenzare fortemente la media.' },
    kTree: { t: 'Con TREE compilato', wat: 'La quota dei reclami della selezione con almeno un percorso TREE.', bron: ['Reclami con almeno una riga in ' + C('OORDLIB.PFKLACHTT') + '.'], let: 'Più questa percentuale è bassa, meno rappresentativi sono i grafici e gli elenchi TREE.' },
    evolutie: { t: 'Andamento', wat: 'Il numero di reclami (o il costo NTR) per mese, trimestre o anno, secondo la data del reclamo. Tutti i filtri sono applicati.', bron: ['Periodo: ' + C('KDATE') + ' in ' + S + '.', 'Costo NTR: vedi le cifre chiave.'], let: 'L’ultimo periodo di solito non è ancora completo ed è quindi più basso.' },
    mode: { t: 'Grafico: linea temporale o anni cumulati', wat: '<b>Linea temporale</b>: il periodo scelto da sinistra a destra, con il numero (o il costo) per mese, trimestre o anno.<br><b>Intervento e seguito</b>: per periodo, la quota di reclami con intervento e quella dei reclami di seguito.<br><b>Anni cumulati</b>: una linea per anno, da gennaio a dicembre, sommando ogni settimana (o mese) alla precedente. Si vede a colpo d’occhio se un anno cresce più o meno velocemente dei precedenti.', bron: ['Data del reclamo: ' + C('KDATE') + ' in ' + S + '.'], let: 'In «Anni cumulati» il filtro del periodo è ignorato (gli altri filtri valgono). L’anno in corso si ferma all’ultimo reclamo. Le settimane contano dal 1° gennaio (giorni 1–7 = settimana 1); non sono settimane ISO. Con le caselle sotto il grafico scegli gli anni mostrati; la scelta viene ricordata in questo browser.' },
    target: { t: 'Obiettivo anno in corso', wat: 'Traccia una linea obiettivo tratteggiata per l’anno in corso: la curva cumulata dell’anno scorso ridotta della percentuale scelta. Se i reclami di quest’anno restano sotto questa linea, sei in linea.', bron: ['Calcolato dalla linea dell’anno scorso nella stessa selezione.'] },
    split: { t: 'Suddividi per', wat: 'Mostra una linea per valore invece di un totale. I 7 valori maggiori hanno una propria linea; il resto è sommato in «Altri».', bron: ['Gli stessi campi dei filtri con lo stesso nome.'], let: 'Per TREE i reclami senza TREE non contano e un reclamo con più percorsi conta in ciascuno.' },
    top: { t: 'Dove sono i reclami?', wat: 'I rami TREE, prodotti, codici NTR e clienti più frequenti nella selezione attuale. La percentuale è la quota sul totale dei reclami della selezione. Clicca su una barra per filtrare.', bron: ['TREE: ' + C('OORDLIB.PFKLACHTT') + '. Prodotti, codici NTR e clienti: vedi i filtri.'], let: 'Per TREE un reclamo può comparire in più rami; le percentuali possono superare il 100% in totale.' },
    lijst: { t: 'Reclami', wat: 'I reclami della selezione, i più recenti per primi. Clicca sul titolo di una colonna per ordinare e su un reclamo per tutti i dettagli. «Esporta in Excel» fornisce l’intera selezione (non solo la pagina mostrata).', bron: ['Dettaglio da ' + S + ': ordine (' + C('KORNR') + '), ordine NTR (' + C('KNORDER') + '), gestito da (' + C('KBEHA') + '), date per fase: in gestione (' + C('KDATB') + '), in magazzino (' + C('KDATM') + '), al servizio di posa (' + C('KDATD') + '), risolto per il cliente (' + C('KDATK') + '), chiuso (' + C('KDATA') + ').', 'Causa e misure: ' + C('OORDLIB.PFKLACHTBH') + '.', '«Apri in WinPro» apre il reclamo in WinPro (solo nella rete Winsol).'] },
  },
};

